const VERSION="explorers-99f4d715187a",FILES=["./","./index.html","./manifest.webmanifest","./icon.svg","./assets/photos/credits.json","./assets/models/manifest.json","./assets/index-9SC6FZna.js","./assets/index-i1_bQXxr.css","./assets/museum-Bh-IRniG.js","./assets/photos/apollo.jpg","./assets/photos/insight.jpg","./assets/photos/opportunity.jpg","./assets/photos/spirit.jpg","./assets/photos/surveyor.jpg","./assets/photos/viking.jpg"];self.addEventListener('install',e=>e.waitUntil(caches.open(VERSION).then(c=>c.addAll(FILES))));self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('explorers-')&&k!==VERSION).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));self.addEventListener('fetch',e=>{const u=new URL(e.request.url);if(e.request.method!=='GET'||u.origin!==location.origin||!u.pathname.startsWith('/explore/')||u.pathname.endsWith('.glb'))return;if(e.request.mode==='navigate'){e.respondWith(fetch(e.request).catch(()=>caches.match('./index.html')));return;}e.respondWith(caches.match(e.request).then(c=>c||fetch(e.request)));});